using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Windows.Media.Media3D;
namespace GearLab {
 // The authoritative STEP is remeshed for printing; viewport triangles are not manufacturing data.
 public static class NativePrintMesh {
  struct Cell:IEquatable<Cell>{public long X,Y,Z;public Cell(long x,long y,long z){X=x;Y=y;Z=z;}public bool Equals(Cell b){return X==b.X&&Y==b.Y&&Z==b.Z;}public override bool Equals(object b){return b is Cell&&Equals((Cell)b);}public override int GetHashCode(){unchecked{return X.GetHashCode()*73856093^Y.GetHashCode()*19349663^Z.GetHashCode()*83492791;}}}
  struct Key:IEquatable<Key>{public int A,B,C;public Key(int a,int b,int c){var q=new[]{a,b,c};Array.Sort(q);A=q[0];B=q[1];C=q[2];}public bool Equals(Key x){return A==x.A&&B==x.B&&C==x.C;}public override bool Equals(object x){return x is Key&&Equals((Key)x);}public override int GetHashCode(){unchecked{return A*73856093^B*19349663^C*83492791;}}}
  sealed class Facet {public int Balance;public int[] Positive,Negative;}
  sealed class Edge {public int Count,A,B;}
  const double Tolerance=.0001;
  static ulong EdgeKey(int a,int b){return ((ulong)(uint)Math.Min(a,b)<<32)|(uint)Math.Max(a,b);}
  static Dictionary<ulong,Edge> Edges(List<int[]> faces){var result=new Dictionary<ulong,Edge>();foreach(var f in faces)for(int i=0;i<3;i++){int a=f[i],b=f[(i+1)%3];ulong key=EdgeKey(a,b);Edge e;if(!result.TryGetValue(key,out e))result[key]=e=new Edge{A=a,B=b};e.Count++;}return result;}
  public static SceneMesh Load(CadPart part,CADKernel kernel){string path=Path.Combine(kernel.Folder,"print-"+Guid.NewGuid().ToString("N")+".stl");try{var doc=CADDocument.ImportStep(Convert.FromBase64String(part.NativeStep),part.Label);if(part.PrintAngles!=null){var a=part.PrintAngles;doc.Features[0].Transform=CADNativeBridge.Transform(RobotMath.Rotation(new Vector3D(1,0,0),a[0])*RobotMath.Rotation(new Vector3D(0,1,0),a[1])*RobotMath.Rotation(new Vector3D(0,0,1),a[2]));}kernel.Run(doc,"export_stl",path,null,null,new Dictionary<string,object>{{"PrepareForPrint",true}});return Read(path);}catch(Exception ex){throw new Exception(part.Label+" ["+part.Id+"]: "+ex.Message,ex);}finally{if(File.Exists(path))File.Delete(path);}}
  static SceneMesh Read(string path){var points=new List<Point3D>();var cells=new Dictionary<Cell,List<int>>();var facets=new Dictionary<Key,Facet>();
   Func<Point3D,int> weld=p=>{var k=new Cell((long)Math.Floor(p.X/Tolerance),(long)Math.Floor(p.Y/Tolerance),(long)Math.Floor(p.Z/Tolerance));for(int x=-1;x<=1;x++)for(int y=-1;y<=1;y++)for(int z=-1;z<=1;z++){List<int> ids;if(!cells.TryGetValue(new Cell(k.X+x,k.Y+y,k.Z+z),out ids))continue;foreach(int i in ids)if((points[i]-p).LengthSquared<=Tolerance*Tolerance)return i;}int next=points.Count;points.Add(p);List<int> list;if(!cells.TryGetValue(k,out list))cells[k]=list=new List<int>();list.Add(next);return next;};
   using(var r=new BinaryReader(File.OpenRead(path))){r.ReadBytes(80);uint count=r.ReadUInt32();if(count>3000000||new FileInfo(path).Length!=84L+50L*count)throw new Exception("Некорректный native STL.");for(uint t=0;t<count;t++){r.ReadBytes(12);var ids=new int[3];for(int i=0;i<3;i++){var p=new Point3D(r.ReadSingle(),r.ReadSingle(),r.ReadSingle());if(!MechanismCad.Finite(p.X)||!MechanismCad.Finite(p.Y)||!MechanismCad.Finite(p.Z))throw new Exception("STL содержит некорректные координаты.");ids[i]=weld(p);}r.ReadUInt16();if(ids.Distinct().Count()!=3||Vector3D.CrossProduct(points[ids[1]]-points[ids[0]],points[ids[2]]-points[ids[0]]).LengthSquared<1e-18)continue;int parity=0;for(int i=0;i<3;i++)for(int j=i+1;j<3;j++)if(ids[i]>ids[j])parity++;var key=new Key(ids[0],ids[1],ids[2]);Facet f;if(!facets.TryGetValue(key,out f))facets[key]=f=new Facet();if(parity%2==0){f.Balance++;f.Positive=ids;}else{f.Balance--;f.Negative=ids;}}}
   var faces=facets.Values.Where(f=>f.Balance!=0).Select(f=>f.Balance>0?f.Positive:f.Negative).ToList();var edges=Edges(faces);if(edges.Values.Any(e=>e.Count>2))throw new Exception("Native STL содержит неманифолдные рёбра.");var boundary=edges.Values.Where(e=>e.Count==1).ToList();var nextEdge=new Dictionary<int,int>();foreach(var e in boundary){if(nextEdge.ContainsKey(e.A))throw new Exception("Разветвлённый шов native STL.");nextEdge[e.A]=e.B;}var visited=new HashSet<int>();foreach(var edge in boundary){if(visited.Contains(edge.A))continue;var loop=new List<int>();int current=edge.A;do{if(!visited.Add(current)||!nextEdge.ContainsKey(current))throw new Exception("Незамкнутый шов native STL.");loop.Add(current);current=nextEdge[current];}while(current!=edge.A);Cap(points,faces,loop);}
   if(Edges(faces).Values.Any(e=>e.Count!=2))throw new Exception("Не удалось замкнуть native STL.");var mesh=new SceneMesh{Points=points.ToArray(),Normals=new Vector3D[points.Count],Indices=faces.SelectMany(f=>f).ToArray()};if(mesh.SignedVolume()<=0)throw new Exception("Некорректный объём native STL.");return mesh;
  }
  static void Cap(List<Point3D> points,List<int[]> faces,List<int> loop){if(loop.Count<3||loop.Count>512)throw new Exception("Слишком большой шов native STL.");var n=new Vector3D();double perimeter=0;for(int i=0;i<loop.Count;i++){var a=points[loop[i]];var b=points[loop[(i+1)%loop.Count]];n+=Vector3D.CrossProduct((Vector3D)a,(Vector3D)b);perimeter+=(b-a).Length;}double area=n.Length/2;if(perimeter<=0||2*area/perimeter>.02||n.Length<1e-12)throw new Exception("Зазор сетки превышает точность STL.");n.Normalize();var origin=points[loop[0]];if(loop.Any(i=>Math.Abs(Vector3D.DotProduct(points[i]-origin,n))>.01))throw new Exception("Неплоский шов native STL.");int skip=Math.Abs(n.X)>Math.Abs(n.Y)?(Math.Abs(n.X)>Math.Abs(n.Z)?0:2):(Math.Abs(n.Y)>Math.Abs(n.Z)?1:2);Func<int,double[]> xy=i=>{var p=points[i];return skip==0?new[]{p.Y,p.Z}:skip==1?new[]{p.X,p.Z}:new[]{p.X,p.Y};};Func<int,int,int,double> cross=(a,b,c)=>{var p=xy(a);var q=xy(b);var r=xy(c);return (q[0]-p[0])*(r[1]-p[1])-(q[1]-p[1])*(r[0]-p[0]);};double signed=0;for(int i=0;i<loop.Count;i++){var a=xy(loop[i]);var b=xy(loop[(i+1)%loop.Count]);signed+=a[0]*b[1]-a[1]*b[0];}double sign=Math.Sign(signed);var remaining=new List<int>(loop);while(remaining.Count>3){bool found=false;for(int i=0;i<remaining.Count;i++){int a=remaining[(i+remaining.Count-1)%remaining.Count],b=remaining[i],c=remaining[(i+1)%remaining.Count];if(cross(a,b,c)*sign<=1e-12)continue;if(remaining.Any(v=>v!=a&&v!=b&&v!=c&&cross(a,b,v)*sign>=-1e-12&&cross(b,c,v)*sign>=-1e-12&&cross(c,a,v)*sign>=-1e-12))continue;faces.Add(new[]{a,c,b});remaining.RemoveAt(i);found=true;break;}if(!found)throw new Exception("Не удалось триангулировать шов STL.");}faces.Add(new[]{remaining[0],remaining[2],remaining[1]});}
 }
}
